create or replace function public.canonical_pvp_expected_score(p_player integer,p_opponent integer) returns numeric language sql immutable as $$ select 1::numeric/(1+power(10::numeric,(p_opponent-p_player)::numeric/400)) $$;
create or replace function public.canonical_pvp_rating_delta(p_player integer,p_opponent integer,p_result text) returns integer language plpgsql immutable as $$
declare v_expected numeric:=public.canonical_pvp_expected_score(p_player,p_opponent);
begin if p_result='WIN' then return round(32*(1-v_expected)); elsif p_result='LOSS' then return round(16*(0-v_expected)); end if; raise exception 'invalid PvP result' using errcode='22023'; end $$;
create or replace function public.canonical_pvp_soft_reset(p_rating integer) returns integer language sql immutable as $$ select greatest(0,1000+floor((p_rating-1000)*0.5)::integer) $$;

update public.pvp_match_rewards_master set diamond_reward=0,exp_reward=0,cash_reward=case result when 'VICTORY' then 500 when 'DEFEAT' then 250 else cash_reward end where result in('VICTORY','DEFEAT');

create or replace function public.get_pvp_opponents(p_user_id uuid,p_my_points integer) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_my_power bigint; v_result jsonb;
begin
 if auth.uid() is null or auth.uid()<>p_user_id then raise exception 'not authorized' using errcode='42501'; end if;
 select coalesce(total_power,0) into v_my_power from public.user_power_rankings where user_id=p_user_id;
 with candidates as (
  select player.id,player.username,coalesce(rank.rank_points,1000) rating,coalesce(power.total_power,0) total_power,coalesce(deck.tactic,'BALANCED') tactic,
   deck.character_1_id,deck.character_2_id,deck.character_3_id,deck.character_4_id,deck.character_5_id,
   case
    when abs(coalesce(rank.rank_points,1000)-coalesce(p_my_points,1000))<=300 and (coalesce(v_my_power,0)<=0 or coalesce(power.total_power,0)*10000 between v_my_power*7000 and v_my_power*14000) then 1
    when abs(coalesce(rank.rank_points,1000)-coalesce(p_my_points,1000))<=500 and (coalesce(v_my_power,0)<=0 or coalesce(power.total_power,0)*10000 between v_my_power*5000 and v_my_power*18000) then 2
    else 3 end match_tier
  from public.users player join public.pvp_defense_decks deck on deck.user_id=player.id
  left join public.pvp_ranks rank on rank.user_id=player.id left join public.user_power_rankings power on power.user_id=player.id
  where player.id<>p_user_id and deck.character_1_id is not null
 ), selected as (select * from candidates order by match_tier,abs(rating-coalesce(p_my_points,1000)),id limit 5)
 select coalesce(jsonb_agg(jsonb_build_object('opponent_user_id',id,'opponent_username',username,'opponent_points',rating,'opponent_power',total_power,'opponent_rank',(select count(distinct r.rank_points)+1 from public.pvp_ranks r where r.rank_points>selected.rating),'match_tier',match_tier,
  'rating_difference',rating-coalesce(p_my_points,1000),'opponent_class',case when rating-coalesce(p_my_points,1000)>=101 then 'STRONGER' when rating-coalesce(p_my_points,1000)<=-101 then 'WEAKER' else 'EQUAL' end,
  'win_rating_delta',public.canonical_pvp_rating_delta(coalesce(p_my_points,1000),rating,'WIN'),'loss_rating_delta',public.canonical_pvp_rating_delta(coalesce(p_my_points,1000),rating,'LOSS'),
  'tactic',tactic,'defense_character_ids',to_jsonb(array_remove(array[character_1_id,character_2_id,character_3_id,character_4_id,character_5_id]::text[],null)),
  'defense_characters',coalesce((select jsonb_agg(jsonb_build_object('slot',slot.slot_no,'character_master_id',release.character_id,'display_name',release.display_name,'rarity',release.rarity,'level',coalesce(owned.level,1),'asset_identifier',release.asset_path) order by slot.slot_no) from (values(1,character_1_id),(2,character_2_id),(3,character_3_id),(4,character_4_id),(5,character_5_id))slot(slot_no,owned_or_master_id) left join public.user_characters owned on owned.user_id=selected.id and owned.id::text=slot.owned_or_master_id join public.character_release_master release on release.character_id=coalesce(owned.character_id,slot.owned_or_master_id) and release.is_enabled where slot.owned_or_master_id is not null),'[]'::jsonb)) order by match_tier,abs(rating-coalesce(p_my_points,1000)),id),'[]'::jsonb) into v_result from selected;
 return v_result;
end $$;

create or replace function public.finalize_pvp_battle(p_replay_id uuid,p_result jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_replay public.battle_replay_sessions%rowtype; v_win boolean; v_player integer; v_opponent integer; v_delta integer; v_cash integer; v_new integer; v_final jsonb; v_name text;
begin
 select * into v_replay from public.battle_replay_sessions where id=p_replay_id for update;
 if not found then raise exception 'PvP replay not found' using errcode='P0002'; end if;
 if v_replay.battle_mode<>'PVP' or v_replay.resolution_authority<>'PVP_SERVER' then raise exception 'replay is not official PvP' using errcode='42501'; end if;
 if v_replay.finalization_status='FINALIZED' then return v_replay.finalization_result; end if;
 if v_replay.status<>'PENDING' or v_replay.finalization_status<>'PENDING' then raise exception 'PvP replay is not finalizable' using errcode='23514'; end if;
 perform public.validate_official_battle_result(p_result); v_win:=p_result->>'winner'='PLAYER';
 v_player:=coalesce((v_replay.official_context->>'playerRankPointsAtStart')::integer,1000); v_opponent:=coalesce((v_replay.official_context->>'opponentRankPointsAtStart')::integer,1000);
 v_delta:=public.canonical_pvp_rating_delta(v_player,v_opponent,case when v_win then 'WIN' else 'LOSS' end); v_cash:=case when v_win then 500 else 250 end;
 insert into public.pvp_ranks(user_id,rank_points,daily_wins,season_wins,updated_at) values(v_replay.requester_user_id,greatest(1000+v_delta,0),case when v_win then 1 else 0 end,case when v_win then 1 else 0 end,now())
 on conflict(user_id) do update set rank_points=greatest(public.pvp_ranks.rank_points+v_delta,0),daily_wins=public.pvp_ranks.daily_wins+case when v_win then 1 else 0 end,season_wins=public.pvp_ranks.season_wins+case when v_win then 1 else 0 end,updated_at=now() returning rank_points into v_new;
 update public.users set cash=cash+v_cash where id=v_replay.requester_user_id;
 select username into v_name from public.users where id=v_replay.requester_user_id;
 insert into public.pvp_defense_logs(user_id,attacker_id,attacker_name,result,points_change) values(v_replay.source_reference_id,v_replay.requester_user_id,v_name,case when v_win then 'DEFEAT' else 'VICTORY' end,-v_delta);
 v_final:=p_result||jsonb_build_object('mode','PVP','oldRating',v_player,'opponentRating',v_opponent,'rankDelta',v_delta,'newRankPoints',v_new,'remainingPvpPoints',coalesce((v_replay.official_context->>'remainingPvpPoints')::integer,0),'rewards',jsonb_build_object('cash',v_cash,'diamonds',0,'xp',0));
 insert into public.battle_replay_events(battle_replay_session_id,event_index,round_number,event_type,payload) select p_replay_id,greatest(coalesce((e.value->>'index')::integer,e.ordinality::integer-1),0),greatest(coalesce((e.value->>'round')::integer,1),1),coalesce(nullif(e.value->>'type',''),'UNKNOWN'),coalesce(e.value->'payload','{}'::jsonb) from jsonb_array_elements(p_result->'events') with ordinality e(value,ordinality) on conflict do nothing;
 update public.battle_replay_sessions set status='RESOLVED',result=v_final,resolved_at=now(),finalization_status='FINALIZED',finalized_at=now(),finalization_result=v_final where id=p_replay_id; return v_final;
end $$;

create or replace function public.get_pvp_rankings_page(p_limit integer default 50,p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare v_uid uuid:=auth.uid();
begin if v_uid is null then raise exception 'authentication required' using errcode='42501'; end if; if p_limit not between 1 and 100 or p_offset not between 0 and 10000 then raise exception 'invalid pagination' using errcode='22023'; end if;
 return jsonb_build_object('rows',coalesce((with totals as(select rank.user_id,u.username,rank.rank_points score,rank.updated_at achieved_at,coalesce(power.total_power,0) total_power from public.pvp_ranks rank join public.users u on u.id=rank.user_id left join public.user_power_rankings power on power.user_id=rank.user_id),ranked as(select *,rank() over(order by score desc) rank_position from totals) select jsonb_agg(to_jsonb(page) order by score desc,achieved_at,user_id) from(select * from ranked order by score desc,achieved_at,user_id limit p_limit offset p_offset)page),'[]'::jsonb),'selfRank',(with totals as(select user_id,rank_points score,updated_at achieved_at from public.pvp_ranks),ranked as(select *,rank() over(order by score desc) rank_position from totals) select to_jsonb(ranked) from ranked where user_id=v_uid));
end $$;

create or replace function public.finalize_pvp_season_rewards(p_season_id uuid) returns integer language plpgsql security definer set search_path=public as $$
declare row record; reward record; granted integer:=0;
begin
 if not exists(select 1 from public.ranking_seasons where id=p_season_id and ranking_type='PVP' and ends_at<=clock_timestamp()) then raise exception 'PvP season is not finalizable' using errcode='23514'; end if;
 for row in with ranked as(select rank.user_id,rank.rank_points,rank() over(order by rank.rank_points desc) pos from public.pvp_ranks rank) select * from ranked where pos<=50 loop
  for reward in select * from public.canonical_pvp_ranking_rewards where version='2026-08-22' and row.pos between rank_min and rank_max loop
   insert into public.pvp_ranking_reward_grants(season_id,user_id,rank_position,item_id,quantity) values(p_season_id,row.user_id,row.pos,reward.item_id,reward.quantity) on conflict do nothing;
   if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(row.user_id,reward.item_id,reward.quantity,'PvPシーズンランキング報酬','UNCLAIMED',now()+interval '30 days');granted:=granted+1; end if;
  end loop;
 end loop; return granted;
end $$;

