$$;

create or replace function public.grant_canonical_raid_reward(p_instance uuid,p_user uuid,p_type text,p_key text) returns integer language plpgsql security definer set search_path=public as $$
declare row record; granted integer:=0;
begin for row in select * from public.canonical_raid_reward_master where version='2026-08-22' and reward_type=p_type and reward_key=p_key loop
 insert into public.raid_production_reward_grants values(p_instance,p_user,p_type,p_key,row.item_id,row.quantity,now()) on conflict do nothing;
 if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(p_user,row.item_id,row.quantity,'レイド報酬','UNCLAIMED',now()+interval '30 days'); granted:=granted+1; end if;
 end loop; return granted; end $$;

create or replace function public.rotate_daily_raids() returns void language plpgsql security definer set search_path=public as $$
declare v_today date:=(clock_timestamp() at time zone 'Asia/Tokyo')::date; v_pair text[]; v_town text; v_master record; v_start timestamptz; v_end timestamptz;
begin
 perform pg_advisory_xact_lock(hashtextextended('CANONICAL_RAID_ROTATION',0));
 for v_master in select id from public.raid_bosses where status='ACTIVE' and expires_at<=clock_timestamp() for update loop perform public.finalize_expired_raid_instance(v_master.id); end loop;
 if exists(select 1 from public.raid_bosses where status='ACTIVE' and expires_at>clock_timestamp()) then return; end if;
 v_pair:=public.canonical_raid_rotation_pair(v_today); v_start:=(v_today::timestamp at time zone 'Asia/Tokyo'); v_end:=v_start+interval '24 hours';
 foreach v_town in array v_pair loop
  select * into v_master from public.canonical_raid_boss_master where town_id=v_town and is_production_enabled;
  insert into public.raid_bosses(boss_id,boss_master_id,current_hp,max_hp,base_id,status,spawned_at,expires_at,cycle_id,rotation_date) values(v_master.boss_id,v_master.boss_id,v_master.max_hp,v_master.max_hp,v_town,'ACTIVE',v_start,v_end,gen_random_uuid(),v_today);
 end loop;
end $$;

create or replace function public.get_active_raids() returns jsonb language plpgsql security definer set search_path=public as $$
begin if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if; perform public.rotate_daily_raids();
 return coalesce((select jsonb_agg(jsonb_build_object('id',boss.id,'bossMasterId',master.boss_id,'bossName',master.display_name,'profileType',master.profile_type,'attribute',master.attribute,'level',master.reference_level,'currentHp',boss.current_hp,'maxHp',boss.max_hp,'baseId',boss.base_id,'spawnedAt',boss.spawned_at,'expiresAt',boss.expires_at,'status',boss.status,'skillLoadout',master.skill_loadout) order by boss.base_id) from public.raid_bosses boss join public.canonical_raid_boss_master master on master.boss_id=boss.boss_master_id where boss.status='ACTIVE' and boss.expires_at>clock_timestamp()),'[]'::jsonb);
end $$;

create or replace function public.start_raid_battle(p_instance_id uuid,p_character_ids text[],p_tactic text default 'ATTACK_PRIORITY') returns jsonb language plpgsql security definer set search_path=public as $$
declare v_uid uuid:=auth.uid(); v_user public.users%rowtype; v_instance record; v_cost integer; v_cost_type text; v_guild uuid; v_players jsonb; v_enemy jsonb; v_replay uuid; v_seed bigint;
begin
 if v_uid is null then raise exception 'authentication required' using errcode='42501'; end if;
 if p_tactic not in('ATTACK_PRIORITY','HEAL_PRIORITY','SKILL_PRIORITY','BALANCED','WEAKNESS_FOCUS') then raise exception 'invalid tactic' using errcode='22023'; end if;
 perform public.sync_and_recover_vitality_and_pvp_points(v_uid); select * into v_user from public.users where id=v_uid for update;
 if v_user.level<5 then raise exception 'player level 5 is required' using errcode='23514'; end if;
 select boss.*,master.display_name,master.attribute,master.reference_level,master.atk,master.def,master.spd,master.luk,master.skill_loadout,master.profile_type into v_instance from public.raid_bosses boss join public.canonical_raid_boss_master master on master.boss_id=boss.boss_master_id where boss.id=p_instance_id and boss.status='ACTIVE' and boss.expires_at>clock_timestamp() for update of boss;
 if not found then raise exception 'Raid instance is not active' using errcode='P0002'; end if;
 if not v_user.raid_free_entry_consumed then v_cost:=0;v_cost_type:='FREE_FIRST';update public.users set raid_free_entry_consumed=true where id=v_uid;
 elsif v_user.raid_points>=1 then v_cost:=1;v_cost_type:='RAID_POINT';update public.users set raid_points=raid_points-1,raid_points_last_recovered_at=case when raid_points=5 then now() else raid_points_last_recovered_at end where id=v_uid;v_user.raid_points:=v_user.raid_points-1;
 else raise exception 'insufficient Raid points' using errcode='23514'; end if;
 select guild_id into v_guild from public.guild_members where user_id=v_uid;
 v_players:=public.build_server_battle_snapshot(v_uid,p_character_ids,'PLAYER');
 v_enemy:=jsonb_build_array(jsonb_build_object('id','raid_'||v_instance.id,'characterId',v_instance.boss_master_id,'name',v_instance.display_name,'team','ENEMY','alignment',v_instance.attribute,'level',v_instance.reference_level,'profileType',v_instance.profile_type,'stats',jsonb_build_object('hp',v_instance.max_hp,'atk',v_instance.atk,'def',v_instance.def,'spd',v_instance.spd,'luk',v_instance.luk),'skills',v_instance.skill_loadout));
 v_seed:=floor(random()*2147483646)::bigint+1;
 insert into public.battle_replay_sessions(requester_user_id,battle_mode,source_reference_id,tactic_id,random_seed,player_snapshot,enemy_snapshot,resolution_authority,finalization_status,official_context) values(v_uid,'RAID',p_instance_id,p_tactic,v_seed,v_players,v_enemy,'RAID_SERVER','PENDING',jsonb_build_object('guildIdSnapshot',v_guild,'costType',v_cost_type,'cost',v_cost,'remainingRaidPoints',v_user.raid_points,'bossHpAtStart',v_instance.current_hp,'bossMaxHp',v_instance.max_hp,'baseId',v_instance.base_id,'bossProfile',v_instance.profile_type)) returning id into v_replay;
 return jsonb_build_object('replay_session_id',v_replay,'player_snapshot',v_players,'enemy_snapshot',v_enemy,'cost_type',v_cost_type,'cost',v_cost,'remaining_raid_points',v_user.raid_points,'guild_id_snapshot',v_guild);
end $$;

create or replace function public.finalize_raid_battle(p_replay_id uuid,p_result jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_replay public.battle_replay_sessions%rowtype; v_instance public.raid_bosses%rowtype; v_raw bigint; v_applied bigint; v_remaining bigint; v_total bigint; v_progress record; v_final jsonb;
begin
 select * into v_replay from public.battle_replay_sessions where id=p_replay_id for update;
 if not found or v_replay.battle_mode<>'RAID' or v_replay.resolution_authority<>'RAID_SERVER' then raise exception 'not an official Raid replay' using errcode='42501'; end if;
 if v_replay.finalization_status='FINALIZED' then return v_replay.finalization_result; end if;
 if v_replay.status<>'PENDING' or v_replay.finalization_status<>'PENDING' then raise exception 'Raid replay is not finalizable' using errcode='23514'; end if;
 perform public.validate_official_battle_result(p_result); select * into v_instance from public.raid_bosses where id=v_replay.source_reference_id for update; if not found then raise exception 'Raid instance missing'; end if;
 v_raw:=greatest(coalesce((p_result->>'playerRawDamage')::bigint,0),0);v_applied:=least(v_raw,greatest(v_instance.current_hp,0));v_remaining:=greatest(v_instance.current_hp-v_applied,0);
 update public.raid_bosses set current_hp=v_remaining,status=case when v_remaining=0 then 'DEFEATED' else status end where id=v_instance.id;
 insert into public.raid_damage_logs(boss_id,raid_boss_id,user_id,damage,damage_dealt,raid_boss_instance_id,battle_replay_session_id,guild_id,raw_damage,applied_damage) values(v_instance.boss_id,v_instance.boss_id,v_replay.requester_user_id,v_raw,v_raw,v_instance.id,p_replay_id,nullif(v_replay.official_context->>'guildIdSnapshot','')::uuid,v_raw,v_applied);
 insert into public.raid_instance_user_progress(raid_boss_instance_id,user_id,finalized_battles,raid_points_consumed,last_guild_id) values(v_instance.id,v_replay.requester_user_id,1,case when v_replay.official_context->>'costType'='RAID_POINT' then 1 else 0 end,nullif(v_replay.official_context->>'guildIdSnapshot','')::uuid)
 on conflict(raid_boss_instance_id,user_id) do update set finalized_battles=public.raid_instance_user_progress.finalized_battles+1,raid_points_consumed=public.raid_instance_user_progress.raid_points_consumed+excluded.raid_points_consumed,last_guild_id=excluded.last_guild_id,updated_at=now() returning * into v_progress;
 for v_final in select jsonb_build_object('reward_key',r.reward_key) from public.canonical_raid_reward_master r where version='2026-08-22' and reward_type='PROGRESS' and (r.finalized_battles is null or r.finalized_battles<=v_progress.finalized_battles) and (r.raid_points_consumed is null or r.raid_points_consumed<=v_progress.raid_points_consumed) group by r.reward_key loop perform public.grant_canonical_raid_reward(v_instance.id,v_replay.requester_user_id,'PROGRESS',v_final->>'reward_key'); end loop;
 select coalesce(sum(raw_damage),0) into v_total from public.raid_damage_logs where raid_boss_instance_id=v_instance.id and user_id=v_replay.requester_user_id;
 v_final:=p_result||jsonb_build_object('mode','RAID','raidInstanceId',v_instance.id,'baseId',v_instance.base_id,'rawDamage',v_raw,'appliedDamage',v_applied,'remainingBossHp',v_remaining,'personalContribution',v_total,'guildIdSnapshot',v_replay.official_context->>'guildIdSnapshot','participationProgress',to_jsonb(v_progress));
 insert into public.battle_replay_events(battle_replay_session_id,event_index,round_number,event_type,payload) select p_replay_id,greatest(coalesce((e.value->>'index')::integer,e.ordinality::integer-1),0),greatest(coalesce((e.value->>'round')::integer,1),1),coalesce(nullif(e.value->>'type',''),'UNKNOWN'),coalesce(e.value->'payload','{}'::jsonb) from jsonb_array_elements(p_result->'events') with ordinality e(value,ordinality) on conflict do nothing;
 update public.battle_replay_sessions set status='RESOLVED',result=v_final,resolved_at=now(),finalization_status='FINALIZED',finalized_at=now(),finalization_result=v_final where id=p_replay_id;
 if v_remaining=0 then perform public.finalize_expired_raid_instance(v_instance.id); end if; return v_final;
end $$;

create or replace function public.finalize_expired_raid_instance(p_instance_id uuid) returns void language plpgsql security definer set search_path=public as $$
declare v_instance public.raid_bosses%rowtype; row record;
begin
 select * into v_instance from public.raid_bosses where id=p_instance_id for update; if not found or v_instance.outcome_finalized_at is not null then return; end if;
 if v_instance.status='ACTIVE' and v_instance.expires_at>clock_timestamp() then return; end if;
 update public.raid_bosses set status=case when current_hp=0 then 'DEFEATED' else 'EXPIRED' end,outcome=case when current_hp=0 then 'DEFEAT_SUCCESS' else 'TIMEOUT_FAILURE' end,outcome_finalized_at=now() where id=p_instance_id;
 if v_instance.current_hp=0 then for row in select distinct user_id from public.raid_damage_logs where raid_boss_instance_id=p_instance_id loop perform public.grant_canonical_raid_reward(p_instance_id,row.user_id,'CLEAR','CLEAR'); end loop; end if;
 for row in with totals as(select user_id,sum(raw_damage)::bigint score,min(created_at) achieved_at from public.raid_damage_logs where raid_boss_instance_id=p_instance_id group by user_id),ranked as(select *,rank() over(order by score desc) pos from totals) select * from ranked where pos<=10 loop
  perform public.grant_canonical_raid_reward(p_instance_id,row.user_id,'PERSONAL_RANK',case when row.pos=1 then 'RANK_1_1' when row.pos<=3 then 'RANK_2_3' else 'RANK_4_10' end);
 end loop;
 for row in with totals as(select guild_id,sum(raw_damage)::bigint score,min(created_at) achieved_at from public.raid_damage_logs where raid_boss_instance_id=p_instance_id and guild_id is not null group by guild_id),ranked as(select *,rank() over(order by score desc) pos from totals) select ranked.*,member.user_id from ranked join public.guild_members member on member.guild_id=ranked.guild_id where pos<=10 and exists(select 1 from public.raid_damage_logs log where log.raid_boss_instance_id=p_instance_id and log.guild_id=ranked.guild_id and log.user_id=member.user_id) loop
  perform public.grant_canonical_raid_reward(p_instance_id,row.user_id,'GUILD_RANK',case when row.pos=1 then 'RANK_1_1' when row.pos<=3 then 'RANK_2_3' else 'RANK_4_10' end);
 end loop;
end $$;

create or replace function public.get_raid_rankings(p_instance_id uuid,p_limit integer default 100,p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare v_uid uuid:=auth.uid();
begin if v_uid is null then raise exception 'authentication required' using errcode='42501'; end if; if p_limit not between 1 and 100 or p_offset not between 0 and 10000 then raise exception 'invalid pagination' using errcode='22023'; end if;
 return jsonb_build_object(
 'individual',coalesce((with totals as(select log.user_id,u.username,sum(log.raw_damage)::bigint contribution,min(log.created_at) achieved_at from public.raid_damage_logs log join public.users u on u.id=log.user_id where log.raid_boss_instance_id=p_instance_id group by log.user_id,u.username),ranked as(select *,rank() over(order by contribution desc) rank_position from totals) select jsonb_agg(to_jsonb(page) order by contribution desc,achieved_at,user_id) from(select * from ranked order by contribution desc,achieved_at,user_id limit p_limit offset p_offset)page),'[]'::jsonb),
 'guild',coalesce((with totals as(select log.guild_id,g.name guild_name,sum(log.raw_damage)::bigint contribution,min(log.created_at) achieved_at,count(distinct log.user_id)::integer participant_count from public.raid_damage_logs log join public.guilds g on g.id=log.guild_id where log.raid_boss_instance_id=p_instance_id and log.guild_id is not null group by log.guild_id,g.name),ranked as(select *,rank() over(order by contribution desc) rank_position from totals) select jsonb_agg(to_jsonb(page) order by contribution desc,achieved_at,guild_id) from(select * from ranked order by contribution desc,achieved_at,guild_id limit p_limit offset p_offset)page),'[]'::jsonb),
 'selfRank',(with totals as(select user_id,sum(raw_damage)::bigint contribution,min(created_at) achieved_at from public.raid_damage_logs where raid_boss_instance_id=p_instance_id group by user_id),ranked as(select *,rank() over(order by contribution desc) rank_position from totals) select to_jsonb(ranked) from ranked where user_id=v_uid));
end $$;
create or replace function public.get_raid_rankings(p_instance_id uuid) returns jsonb language sql stable security definer set search_path=public as $$ select public.get_raid_rankings(p_instance_id,100,0) $$;

alter table public.canonical_pvp_production_master enable row level security; alter table public.canonical_pvp_ranking_rewards enable row level security; alter table public.canonical_raid_production_master enable row level security; alter table public.canonical_raid_boss_master enable row level security; alter table public.canonical_raid_reward_master enable row level security;
revoke all on public.canonical_pvp_production_master,public.canonical_pvp_ranking_rewards,public.canonical_raid_production_master,public.canonical_raid_boss_master,public.canonical_raid_reward_master from public,anon; grant select on public.canonical_pvp_production_master,public.canonical_pvp_ranking_rewards,public.canonical_raid_production_master,public.canonical_raid_boss_master,public.canonical_raid_reward_master to authenticated;
revoke all on function public.finalize_pvp_battle(uuid,jsonb),public.finalize_pvp_season_rewards(uuid),public.soft_reset_pvp_ratings(),public.finalize_raid_battle(uuid,jsonb),public.finalize_expired_raid_instance(uuid),public.rotate_daily_raids(),public.grant_canonical_raid_reward(uuid,uuid,text,text) from public,anon,authenticated; grant execute on function public.finalize_pvp_battle(uuid,jsonb),public.finalize_pvp_season_rewards(uuid),public.soft_reset_pvp_ratings(),public.finalize_raid_battle(uuid,jsonb),public.finalize_expired_raid_instance(uuid),public.rotate_daily_raids(),public.grant_canonical_raid_reward(uuid,uuid,text,text) to service_role;
revoke all on function public.get_pvp_opponents(uuid,integer),public.get_pvp_rankings_page(integer,integer),public.get_active_raids(),public.start_raid_battle(uuid,text[],text),public.get_raid_rankings(uuid),public.get_raid_rankings(uuid,integer,integer) from public,anon; grant execute on function public.get_pvp_opponents(uuid,integer),public.get_pvp_rankings_page(integer,integer),public.get_active_raids(),public.start_raid_battle(uuid,text[],text),public.get_raid_rankings(uuid),public.get_raid_rankings(uuid,integer,integer) to authenticated;
commit;
notify pgrst,'reload schema';
